def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        current_time = op[1]

        # Remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if current_time >= write_time + ttl:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # Remove the key if it already exists (to re-insert at end)
            if key in cache:
                del cache[key]
            # If cache is full, evict the least recently used (first item)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, current_time)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

